    function hexToRgb(h){
      let x=String(h||"").trim().replace(/^#/,"");
      if(x.length===3)x=x.split("").map(c=>c+c).join("");
      if(!/^[0-9a-fA-F]{6}$/.test(x))return null;
      return {red:parseInt(x.slice(0,2),16),green:parseInt(x.slice(2,4),16),blue:parseInt(x.slice(4,6),16)};
    }

    function parsePaletteText(text){
      const src=String(text||"").trim();
      const found=[]; const seen=new Set();
      const add=rgb=>{
        if(!rgb)return;
        const r=clamp(Math.round(Number(rgb.red)),0,255),g=clamp(Math.round(Number(rgb.green)),0,255),b=clamp(Math.round(Number(rgb.blue)),0,255);
        const k=`${r},${g},${b}`; if(!seen.has(k)){seen.add(k);found.push({red:r,green:g,blue:b});}
      };
      const addHexString=h=>{const v=hexToRgb(h);if(v)add(v);};
      const urlMatch=src.match(/https?:\/\/[^\s"'<>]+/i);
      const target=urlMatch?urlMatch[0]:src;

      // Generic HEX colors anywhere in the pasted text.
      (src.match(/#[0-9a-fA-F]{6}\b/g)||[]).forEach(v=>addHexString(v));
      (src.match(/#[0-9a-fA-F]{3}\b/g)||[]).forEach(v=>addHexString(v));

      // Color Hunt: palette URLs use one continuous 6-digit HEX value after /palette/,
      // e.g. /palette/fff89affc900086e7d1a5f7 (4 x 6-digit colors).
      const ch=target.match(/colorhunt\.co\/palette\/([0-9a-fA-F]{6,})/i);
      if(ch){
        const blob=ch[1];
        for(let i=0;i+6<=blob.length;i+=6){
          const h=blob.slice(i,i+6);
          if(/^[0-9a-fA-F]{6}$/.test(h))addHexString(h);
        }
      }

      // Coolors: /palette/hex-hex-hex and other common separated forms.
      const coolors=target.match(/coolors\.co\/[^\s"'<>]*/i);
      if(coolors){
        const groups=coolors[0].match(/(?:^|[\/_-])([0-9a-fA-F]{6})(?=$|[\/_\-?#])/g)||[];
        groups.forEach(v=>addHexString(v.replace(/[^0-9a-fA-F]/g,'')));
      }

      // Adobe Color / Adobe Express Explore: current share URLs store the palette
      // directly in the `color-palette` query parameter, e.g.
      // color-palette=DDDCC5,958976,611427,1D2326,6A6A61
      // (commas may be percent-encoded as %2C). This is the current format used
      // by Adobe Color Explore URLs.
      try{
        const decodedCurrent=decodeURIComponent(target.replace(/&amp;/gi,"&"));
        const mPalette=decodedCurrent.match(/[?&]color-palette=([^&#]+)/i);
        if(mPalette){
          const parts=mPalette[1].split(/[,;]+/).map(v=>v.trim()).filter(Boolean);
          parts.forEach(v=>{
            const h=v.replace(/^#/,"");
            if(/^[0-9a-fA-F]{6}$/.test(h))addHexString(h);
            else if(/^[0-9a-fA-F]{3}$/.test(h))addHexString(h);
          });
        }
      }catch(_){ }

      // Adobe Color: support legacy/share URLs containing rgbvalues, including
      // URLs copied from the browser where the query string may be percent-encoded.
      // Adobe Color historically stores 5 RGB triples as normalized 0..1 values.
      try{
        const decoded=decodeURIComponent(target.replace(/&amp;/gi,"&"));
        const q=(decoded.match(/[?&]rgbvalues=([^&#]+)/i)||decoded.match(/(?:^|[?&])rgbvalues%3D([^&#]+)/i));
        if(q){
          const vals=decodeURIComponent(q[1]).split(/[,;\s]+/).map(Number).filter(Number.isFinite);
          if(vals.length>=3){
            for(let i=0;i+2<vals.length;i+=3){
              const scale=(vals[i]<=1.0001&&vals[i+1]<=1.0001&&vals[i+2]<=1.0001)?255:1;
              add({red:vals[i]*scale,green:vals[i+1]*scale,blue:vals[i+2]*scale});
            }
          }
        }
      }catch(_){ }

      // Adobe Color URLs can also expose HEX/RGB values through query text or
      // copied page text. Accept common parameter names without requiring '#'.
      const adobeHexPairs=target.match(/(?:^|[?&])(hex(?:value)?|color|color[1-5]|swatch[1-5])=([0-9a-fA-F]{6})(?=&|$)/gi)||[];
      adobeHexPairs.forEach(v=>{const m=v.match(/=([0-9a-fA-F]{6})(?:&|$)/);if(m)addHexString(m[1]);});
      const adobeRgbTriples=target.match(/(?:^|[?&])(?:rgb|rgbvalue|rgb[1-5])=([0-9.]+)[,;]([0-9.]+)[,;]([0-9.]+)/gi)||[];
      adobeRgbTriples.forEach(v=>{const m=v.match(/=([0-9.]+)[,;]([0-9.]+)[,;]([0-9.]+)/);if(m){const a=+m[1],b=+m[2],c=+m[3],scale=(a<=1.0001&&b<=1.0001&&c<=1.0001)?255:1;add({red:a*scale,green:b*scale,blue:c*scale});}});

      // Also accept Adobe-style explicit RGB query parameters or raw rgb(...).
      const rgbMatches=src.match(/rgb\s*\(\s*\d{1,3}\s*[,;]\s*\d{1,3}\s*[,;]\s*\d{1,3}\s*\)/gi)||[];
      rgbMatches.forEach(v=>{const m=v.match(/(\d{1,3})\s*[,;]\s*(\d{1,3})\s*[,;]\s*(\d{1,3})/);if(m)add({red:+m[1],green:+m[2],blue:+m[3]});});

      // XML-style RGB.
      const xml=src.match(/red\s*=\s*["'](\d{1,3})["'][^>]*green\s*=\s*["'](\d{1,3})["'][^>]*blue\s*=\s*["'](\d{1,3})["']/gi)||[];
      xml.forEach(v=>{const m=v.match(/red\s*=\s*["'](\d+)["'][^>]*green\s*=\s*["'](\d+)["'][^>]*blue\s*=\s*["'](\d+)["']/i);if(m)add({red:+m[1],green:+m[2],blue:+m[3]});});
      return found;
    }

