    async function saveImportedPaletteFromDialog(){
      try{
        const raw = bridgeCoolorsUrl ? (bridgeCoolorsUrl.value ?? bridgeCoolorsUrl.getAttribute("value") ?? bridgeCoolorsUrl.textContent ?? "") : "";
        const text = String(raw).trim();
        if(!text){try{await a0.showAlert("Paste a Coolors palette URL or HEX/RGB/XML colors first.");}catch(_){}return false;}
        const imported=parsePaletteText(text);
        if(!imported.length)throw new Error("No colors found. Please paste a complete Color Hunt, Coolors, or Adobe Color palette URL, or paste HEX/RGB values.");
        const merged=Array.isArray(Q0)?Q0.slice():[];
        const keys=new Set(merged.map(c=>`${c.red},${c.green},${c.blue}`));
        imported.forEach(c=>{const k=`${c.red},${c.green},${c.blue}`;if(!keys.has(k)){keys.add(k);merged.push(c);}});
        Q0=merged;
        await savePalette();
        if(typeof Nr==="function")Nr();
        activateImportedTab();
        hidePaletteQuicklinks();
        return true;
      }catch(err){
        console.error("Save imported palette failed:",err);
        try{await a0.showAlert("Save palette failed: "+(err&&err.message?err.message:err));}catch(_){}
        return false;
      }
    }
